//! 🧪️ Real payload allocation refusal preserves the same original operation and actual marker.
use semio_framework_job_payload::*;
use semio_framework_trace::{OperationId,Generation};
use semio_framework_value_control_contract::{RetainedAllocationEffect,RetainedCloneGrant,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn complete(result:RetainedWorkOutcome)->RetainedWorkPoll<RetainedCloneStep,ValueError>{RetainedWorkPoll::Complete(result)}
fn take(turn:RetainedWorkPoll<RetainedCloneStep,ValueError>)->RetainedWorkOutcome{let RetainedWorkPoll::Complete(turn)=turn else{panic!("original payload birth unexpectedly pending")};turn}
#[test]fn real_payload_allocator_refusal_retains_original_input_and_marker(){
 let law:serde_json::Value=serde_json::from_str(include_str!("payload-birth.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&serde_json::json!({"items":64,"copyBytes":1048576,"capacityBytes":1048576,"releaseBytes":1048576,"depth":64,"fuel":128})));let mut owner=OriginalJobPayloadAdmission::new();let operation=OperationId(7301);let generation=Generation(8);
 let issued=grant(OriginalJobPayloadAdmission::prepare_demand());let(turn,actual)=bank.run(issued,1,|effect|complete(owner.prepare(operation,generation,effect)));let turn=take(turn);assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,(0,0));assert_eq!(bank.take_admitted(),Some(true));assert_eq!(owner.input_identity(),Some((operation,generation)));
 let issued=grant(OriginalJobPayloadAdmission::backing_demand().unwrap());let(((turn,actual),attempts),heap)=observe(||refuse(||bank.run(issued,OriginalJobPayloadAdmission::backing_work_demand(),|effect|complete(owner.admit_backing(effect)))));let turn=take(turn);assert_eq!(attempts,1);assert_eq!(actual,Some(law[1]["actual"].as_u64().unwrap()as usize));assert_eq!(heap,(0,0));assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::AllocationFailed);assert_eq!(owner.input_identity(),Some((operation,generation)));assert_eq!(owner.has_backing(),law[1]["backing"].as_bool().unwrap());assert_eq!(bank.take_admitted(),Some(true));
 let((turn,actual),heap)=observe(||bank.run(issued,OriginalJobPayloadAdmission::backing_work_demand(),|effect|complete(owner.admit_backing(effect))));let turn=take(turn);assert_eq!(actual,Some(issued.maximum_capacity_bytes));let identity=owner.backing_identity().unwrap();bank.post(turn.result.unwrap().progress(),issued,heap);assert_eq!(bank.take_admitted(),Some(true));
 let issued=grant(OriginalJobPayloadAdmission::publication_demand().unwrap());let(turn,actual)=bank.run(issued,OriginalJobPayloadAdmission::publication_work_demand(),|effect|complete(owner.publish(effect)));let turn=take(turn);assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,(0,0));assert_eq!(bank.take_admitted(),Some(true));let issued=grant(OriginalJobPayloadAdmission::take_demand());let mut output=None;let(turn,actual)=bank.run(issued,1,|effect|complete(owner.take_authority(&mut output,effect)));let turn=take(turn);assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,(0,0));assert_eq!(bank.take_admitted(),Some(true));assert_eq!(output.as_ref().unwrap().identity(),Some(identity));assert!(owner.terminal_is_empty());
 for _ in 0..16{if output.as_ref().unwrap().terminal_is_empty(){break}let original=output.as_mut().unwrap();let issued=grant(original.retirement_demands());let work=original.retirement_work_demand().unwrap();let((turn,actual),heap)=observe(||bank.run(issued,work,|effect|complete(original.close_step(effect))));let turn=take(turn);assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,heap);assert_eq!(bank.take_admitted(),Some(true));}assert!(output.as_ref().unwrap().terminal_is_empty());
}
